import re

HEAD = re.compile(r"^(?P<type>[\w.$]+) \{\s*$")
FIELD = re.compile(r"^\s+(?P<key>\w+) = (?P<value>.*?)\s*$")
QUOTED = re.compile(r"^\"(?P<text>[^\"]*)\"(?: \((?P<k>\w+) = (?P<v>[^)]*)\))?$")
FRAME = re.compile(r"^\s+(?P<frame>\S.*?)(?: line: (?P<line>\d+))?\s*$")
CLOSE = re.compile(r"^\s*\}\s*$")
END_LIST = re.compile(r"^\s*\]\s*$")


def parse(lines):
    events = {}         # type -> [record]; one table per event type
    ev_lines = {}       # type -> consumed line indexes
    frames, frame_lines = [], []
    rec, etype, seq = None, "", 0
    path = []           # nested object keys, joined with '.'
    lst = None          # (key, items) while inside a [ ... ] list
    for j, ln in enumerate(lines):
        if not ln.strip():
            continue
        if rec is None:
            m = HEAD.match(ln)
            if m:
                etype = m.group("type")
                seq += 1
                rec = {"event": seq, "type": etype}
                events.setdefault(etype, []).append(rec)
                ev_lines.setdefault(etype, []).append(j)
            continue
        if lst is not None:
            key, items = lst
            if END_LIST.match(ln):
                if key != "stackTrace":
                    rec[key] = "; ".join(items)
                    ev_lines[etype].append(j)
                else:
                    frame_lines.append(j)
                lst = None
            elif key == "stackTrace":
                m = FRAME.match(ln)
                frames.append({"event": seq, "type": etype, "frame": m.group("frame"), "line": m.group("line") or ""})
                frame_lines.append(j)
            else:
                items.append(ln.strip())
                ev_lines[etype].append(j)
            continue
        if CLOSE.match(ln):
            ev_lines[etype].append(j)
            if path:
                path.pop()
            else:
                rec = None
            continue
        m = FIELD.match(ln)
        if not m:
            continue
        key = ".".join(path + [m.group("key")])
        val = m.group("value")
        if val == "[":
            lst = (key, [])
            (frame_lines if key == "stackTrace" else ev_lines[etype]).append(j)
            continue
        ev_lines[etype].append(j)
        if val == "{":
            path.append(m.group("key"))
            continue
        q = QUOTED.match(val)
        if q:
            rec[key] = q.group("text")
            if q.group("k"):
                rec[key + "." + q.group("k")] = q.group("v")
        else:
            rec[key] = val
    blocks = []
    for etype, recs in events.items():
        cols = []
        for r in recs:
            for k in r:
                if k not in cols:
                    cols.append(k)
        recs = [{c: r.get(c, "") for c in cols} for r in recs]
        blocks.append({"name": etype, "kind": "table", "lines": ev_lines[etype], "records": recs})
    blocks.append({"name": "stack frames", "kind": "table", "lines": frame_lines, "records": frames})
    return blocks
